args.sparql:
SELECT ?mother ?motherLabel WHERE {
  dbr:Infante_Antonio_Pascual_of_Spain dbp:mother ?mother .
  OPTIONAL { ?mother rdfs:label ?motherLabel . FILTER(lang(?motherLabel) = "en") }
}

